'use strict';
/* AgentQon Shield — CLI side (v20.2, local-key mode).
 *
 * Three per-install credentials live in ~/.agentqon (dir 0700, files
 * 0600) and are generated by `agentqon setup`:
 *   local-token     the local API token the server demands on every
 *                   route (X-OmniMind-Local-Token); also how the web
 *                   UI proves it belongs to this install.
 *   channel.secret  HMAC key signing every CLI→server request
 *                   (spec §B1: method|path|ts|nonce|body-hash,
 *                   +-120 s window, nonce replay cache server-side).
 *   payload.key     AES-256 key encrypting the installed server
 *                   payload at rest (R3 local-key mode).
 *
 * The release payload itself is verified against a signed manifest:
 * build-payload.js compiles the server to bytecode, hashes every
 * file into manifest.json and signs it with the release Ed25519 key.
 * Only the PUBLIC key lives here — a bundle whose manifest does not
 * verify is refused at setup, and an installed tree whose ciphertext
 * no longer matches its install record is refused at start (with a
 * `agentqon setup --repair` path), per SHIELD_SPEC §A Rung 3.
 */
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const cfgMod = require('./config');

const RELEASE_PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAc1Irm0m3xVce7AU1OtX1NQv6xTvl6E9r2xeCOLzrvh4=
-----END PUBLIC KEY-----
`;

const TOKEN_PATH = () => path.join(cfgMod.configDir(), 'local-token');
const CHANNEL_PATH = () => path.join(cfgMod.configDir(), 'channel.secret');
const PAYLOAD_KEY_PATH = () => path.join(cfgMod.configDir(), 'payload.key');

/* ---------------------------------------------------------- file helpers */
function writeSecretFile(p, contents) {
  fs.mkdirSync(path.dirname(p), { recursive: true, mode: 0o700 });
  fs.writeFileSync(p, contents, { mode: 0o600 });
  try { fs.chmodSync(p, 0o600); } catch { /* best effort */ }
}
function readSecretFile(p) {
  try { return fs.readFileSync(p, 'utf8').trim() || null; } catch { return null; }
}

/* ---------------------------------------------------------- credentials */
function ensureLocalToken() {
  let t = readSecretFile(TOKEN_PATH());
  if (!t) { t = crypto.randomBytes(32).toString('base64url'); writeSecretFile(TOKEN_PATH(), t + '\n'); }
  return t;
}
function ensureChannelSecret() {
  let s = readSecretFile(CHANNEL_PATH());
  if (!s) { s = crypto.randomBytes(32).toString('base64url'); writeSecretFile(CHANNEL_PATH(), s + '\n'); }
  return s;
}
function loadLocalToken() { return readSecretFile(TOKEN_PATH()); }
function loadChannelSecret() { return readSecretFile(CHANNEL_PATH()); }
function ensureCredentials() {
  return { token: ensureLocalToken(), channelSecret: ensureChannelSecret() };
}
/* Rotation (spec §B1): on setup --repair and on demand. The old
 * secret dies immediately — the CLI is the only legitimate client. */
function rotateCredentials() {
  const t = crypto.randomBytes(32).toString('base64url');
  const s = crypto.randomBytes(32).toString('base64url');
  writeSecretFile(TOKEN_PATH(), t + '\n');
  writeSecretFile(CHANNEL_PATH(), s + '\n');
  return { token: t, channelSecret: s };
}
function ensurePayloadKey() {
  const raw = readSecretFile(PAYLOAD_KEY_PATH());
  if (raw) return Buffer.from(raw, 'base64');
  const key = crypto.randomBytes(32);
  writeSecretFile(PAYLOAD_KEY_PATH(), key.toString('base64') + '\n');
  return key;
}
/* Persist a SPECIFIC payload key. Repair generates the new key in
 * memory, encrypts the staged tree with it, and only writes the key
 * file once the new tree is swapped into place — writing it earlier
 * would orphan the still-installed tree (encrypted under the old
 * key) if the process died mid-repair. */
function writePayloadKey(key) {
  writeSecretFile(PAYLOAD_KEY_PATH(), Buffer.from(key).toString('base64') + '\n');
  return key;
}
function rotatePayloadKey() {
  return writePayloadKey(crypto.randomBytes(32));
}
function loadPayloadKey() {
  const raw = readSecretFile(PAYLOAD_KEY_PATH());
  return raw ? Buffer.from(raw, 'base64') : null;
}

/* ---------------------------------------------------------- HMAC channel */
function sha256Hex(data) { return crypto.createHash('sha256').update(data).digest('hex'); }
function signRequest(secret, method, fullPath, bodyStr) {
  const ts = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomBytes(16).toString('hex');
  const canonical = [method.toUpperCase(), fullPath, ts, nonce, sha256Hex(bodyStr || '')].join('\n');
  const sig = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
  return { 'x-omnimind-ts': ts, 'x-omnimind-nonce': nonce, 'x-omnimind-sig': sig };
}

/* ---------------------------------------------------------- bundle verify */
function walkFiles(root) {
  const out = [];
  (function walk(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else out.push(path.relative(root, p).split(path.sep).join('/'));
    }
  })(root);
  return out.sort();
}

/* Verify a bundled (plaintext, pre-install) server tree against its
 * signed release manifest. Returns { shield:false } for a legacy
 * no-manifest bundle (repo-dev), or { shield:true, ok, errors,
 * manifest }. Any mismatch is a hard failure for setup. */
function verifyBundle(bundleDir, onProgress) {
  const manifestPath = path.join(bundleDir, 'manifest.json');
  const sigPath = path.join(bundleDir, 'manifest.sig');
  if (!fs.existsSync(manifestPath)) return { shield: false, ok: true, errors: [] };
  const errors = [];
  const manifestBytes = fs.readFileSync(manifestPath);
  let manifest = null;
  try { manifest = JSON.parse(manifestBytes.toString('utf8')); }
  catch { errors.push('manifest.json is not valid JSON'); }
  if (!fs.existsSync(sigPath)) {
    errors.push('manifest.sig missing — unsigned payload refused');
  } else if (manifest) {
    const sig = Buffer.from(fs.readFileSync(sigPath, 'utf8').trim(), 'base64');
    let ok = false;
    try { ok = crypto.verify(null, manifestBytes, RELEASE_PUBLIC_KEY_PEM, sig); }
    catch { ok = false; }
    if (!ok) errors.push('manifest signature does not verify against the release key');
  }
  if (manifest) {
    const listed = new Set(Object.keys(manifest.files || {}));
    const total = listed.size;
    let done = 0;
    for (const rel of listed) {
      const p = path.join(bundleDir, ...rel.split('/'));
      if (!fs.existsSync(p)) { errors.push(`manifest file missing: ${rel}`); continue; }
      if (sha256Hex(fs.readFileSync(p)) !== manifest.files[rel]) {
        errors.push(`hash mismatch: ${rel}`);
      }
      done++;
      if (onProgress && (done % 200 === 0 || done === total)) onProgress(done, total);
    }
    for (const rel of walkFiles(bundleDir)) {
      if (rel === 'manifest.json' || rel === 'manifest.sig') continue;
      if (!listed.has(rel)) errors.push(`unlisted file in payload: ${rel}`);
    }
  }
  return { shield: true, ok: errors.length === 0, errors, manifest };
}

/* ------------------------------------------------- payload encrypt/decrypt */
const ENC_SUFFIX = '.enc';

function encryptTree(srcDir, destDir, key, meta, onProgress) {
  fs.rmSync(destDir, { recursive: true, force: true });
  fs.mkdirSync(destDir, { recursive: true, mode: 0o700 });
  const record = { ...meta, files: {} };
  const rels = walkFiles(srcDir);
  let done = 0;
  for (const rel of rels) {
    const plain = fs.readFileSync(path.join(srcDir, ...rel.split('/')));
    const iv = crypto.randomBytes(12);
    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
    const ct = Buffer.concat([cipher.update(plain), cipher.final()]);
    const blob = Buffer.concat([iv, cipher.getAuthTag(), ct]);
    const dest = path.join(destDir, ...rel.split('/')) + ENC_SUFFIX;
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, blob);
    record.files[rel] = sha256Hex(blob);
    done++;
    if (onProgress && (done % 100 === 0 || done === rels.length)) onProgress(done, rels.length);
  }
  fs.writeFileSync(path.join(destDir, 'install.json'),
    JSON.stringify(record, null, 2) + '\n', { mode: 0o600 });
  return record;
}

function readInstallRecord(serverDir) {
  try { return JSON.parse(fs.readFileSync(path.join(serverDir, 'install.json'), 'utf8')); }
  catch { return null; }
}

/* Hash every ciphertext file against the install record — the boot
 * tamper check. Returns { ok, bad } where bad is the first offending
 * relative path (modified, missing, or unlisted). */
function verifyInstalled(serverDir, onProgress) {
  const record = readInstallRecord(serverDir);
  if (!record) return { ok: false, bad: '(install record missing)', record: null };
  const entries = Object.entries(record.files || {});
  let done = 0;
  for (const [rel, expected] of entries) {
    const p = path.join(serverDir, ...rel.split('/')) + ENC_SUFFIX;
    if (!fs.existsSync(p)) return { ok: false, bad: rel, record };
    if (sha256Hex(fs.readFileSync(p)) !== expected) return { ok: false, bad: rel, record };
    done++;
    if (onProgress && (done % 200 === 0 || done === entries.length)) onProgress(done, entries.length);
  }
  for (const rel of walkFiles(serverDir)) {
    if (rel === 'install.json') continue;
    if (!rel.endsWith(ENC_SUFFIX)) return { ok: false, bad: rel, record };
    if (!(rel.slice(0, -ENC_SUFFIX.length) in (record.files || {}))) {
      return { ok: false, bad: rel, record };
    }
  }
  return { ok: true, bad: null, record };
}

/* Decrypt the installed payload into the private runtime dir and
 * verify every plaintext hash against the SIGNED manifest the CLI
 * verified at setup (kept in the install record). */
function decryptTree(serverDir, destDir, key, onProgress) {
  const record = readInstallRecord(serverDir);
  if (!record) throw new Error('install record missing — run `agentqon setup --repair`');
  fs.rmSync(destDir, { recursive: true, force: true });
  fs.mkdirSync(destDir, { recursive: true, mode: 0o700 });
  try { fs.chmodSync(destDir, 0o700); } catch { /* best effort */ }
  const rels = Object.keys(record.manifestFiles || {});
  let done = 0;
  for (const rel of rels) {
    const blob = fs.readFileSync(path.join(serverDir, ...rel.split('/')) + ENC_SUFFIX);
    const iv = blob.subarray(0, 12);
    const tag = blob.subarray(12, 28);
    const ct = blob.subarray(28);
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
    decipher.setAuthTag(tag);
    let plain;
    try { plain = Buffer.concat([decipher.update(ct), decipher.final()]); }
    catch { throw new Error(`payload decryption failed for ${rel} — the install is corrupt or the payload key does not match; run \`agentqon setup --repair\``); }
    if (sha256Hex(plain) !== record.manifestFiles[rel]) {
      throw new Error(`payload integrity check failed for ${rel} after decryption — refusing to run a tampered install; run \`agentqon setup --repair\``);
    }
    const dest = path.join(destDir, ...rel.split('/'));
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, plain);
    done++;
    if (onProgress && (done % 200 === 0 || done === rels.length)) onProgress(done, rels.length);
  }
  return record;
}

module.exports = {
  RELEASE_PUBLIC_KEY_PEM,
  ensureLocalToken, ensureChannelSecret, ensureCredentials,
  loadLocalToken, loadChannelSecret, rotateCredentials,
  ensurePayloadKey, rotatePayloadKey, writePayloadKey, loadPayloadKey,
  signRequest, sha256Hex, verifyBundle, encryptTree,
  readInstallRecord, verifyInstalled, decryptTree, walkFiles,
};
